//! `:shortcode:` emoji search for inline input completion and the
//! searchable reaction picker (D83, D103): every emoji up to Emoji 16.0 with
//! its official CLDR keywords (`shortcodes/table.rs`, generated by
//! `tools/emoji/gen_table.py`), plus everyday aliases such as `:thumbsup:`.

mod table;

use self::table::EMOJI;

