/// Maximum number of candidates in the reaction search popup (D104); the
/// list scrolls past [`REACT_SEARCH_ROWS`].
pub const REACT_SEARCH_LIMIT: usize = 50;
/// Rows of candidates the reaction search popup shows at once (D104).
pub const REACT_SEARCH_ROWS: usize = 10;

/// Whether `emoji` is one faro knows (an alias's or any standard emoji),
/// with or without variation selectors.
pub fn is_known(emoji: &str) -> bool {
    let plain = |s: &str| s.chars().filter(|c| *c != '\u{fe0f}').collect::<String>();
    let wanted = plain(emoji);
    !wanted.is_empty()
        && (SHORTCODES.iter().any(|(_, e)| plain(e) == wanted)
            || EMOJI.iter().any(|(e, _, _)| plain(e) == wanted))
}

/// How well an emoji matched, best first (D103).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Tier {
    Alias,
    Code,
    AliasPrefix,
    Keyword,
    CodePrefix,
    WordPrefix,
    CodeContains,
}

/// The emoji for `:query:` typed in full: an alias (`thumbsup`) or an
/// emoji's own code (`smiling_face_with_sunglasses`, `cookie`).
pub fn exact(query: &str) -> Option<&'static str> {
    let query = query.to_ascii_lowercase();
    SHORTCODES
        .iter()
        .find(|(alias, _)| *alias == query)
        .map(|(_, emoji)| *emoji)
        .or_else(|| {
            EMOJI
                .iter()
                .find(|(_, code, _)| *code == query)
                .map(|(emoji, _, _)| *emoji)
        })
}

/// Match `query` (case and surrounding `:` ignored; `_` or `-` between
/// words) against every emoji (D103): the aliases in [`SHORTCODES`], each
/// emoji's code and its official CLDR keywords. Exact aliases and codes
/// come first, then aliases it starts (`heart` → `heart_eyes`), then exact
/// keywords (`cool` finds 😎 and 🆒), then prefixes (`coo` the cook and the
/// cookie too), then codes that merely contain it; within a tier the everyday
/// emoji of [`SHORTCODES`] first, then Unicode's order. Each emoji once,
/// labelled with the alias it matched or its code. An empty query lists
/// the everyday emoji.
pub fn search_shortcodes(query: &str, limit: usize) -> Vec<(&'static str, &'static str)> {
    if limit == 0 {
        return Vec::new();
    }
    let cleaned = query.trim().trim_matches(':').to_ascii_lowercase();
    if cleaned.is_empty() {
        let mut results: Vec<(&'static str, &'static str)> = Vec::with_capacity(limit);
        for &(name, emoji) in SHORTCODES {
            if results.len() < limit && !results.iter().any(|(_, e)| *e == emoji) {
                results.push((name, emoji));
            }
        }
        return results;
    }
    let as_words = cleaned.replace('-', "_");
    let popularity = |emoji: &str| {
        SHORTCODES
            .iter()
            .position(|(_, e)| *e == emoji)
            .unwrap_or(usize::MAX)
    };
    // (tier, popularity, Unicode order, label, emoji)
    let mut found: Vec<(Tier, usize, usize, &'static str, &'static str)> = Vec::new();
    for (order, &(alias, emoji)) in SHORTCODES.iter().enumerate() {
        let tier = if alias == cleaned {
            Some(Tier::Alias)
        } else if alias.starts_with(&cleaned) {
            Some(Tier::AliasPrefix)
        } else {
            None
        };
        if let Some(tier) = tier {
            found.push((tier, order, 0, alias, emoji));
        }
    }
    for (order, &(emoji, code, keywords)) in EMOJI.iter().enumerate() {
        if let Some(tier) = tier(&cleaned, &as_words, code, keywords) {
            found.push((tier, popularity(emoji), order, code, emoji));
        }
    }
    found.sort_by_key(|&(tier, popular, order, _, _)| (tier, popular, order));
    let mut results: Vec<(&'static str, &'static str)> = Vec::with_capacity(limit);
    for (_, _, _, label, emoji) in found {
        if results.len() >= limit {
            break;
        }
        if !results.iter().any(|(_, e)| *e == emoji) {
            results.push((label, emoji));
        }
    }
    results
}

/// How an emoji with `code` and `keywords` matches the query (`as_words`:
/// the query with `-` read as `_`).
fn tier(query: &str, as_words: &str, code: &str, keywords: &str) -> Option<Tier> {
    let mut keywords = keywords.split('|');
    if code == as_words {
        return Some(Tier::Code);
    }
    if keywords
        .clone()
        .any(|k| k == query || k.replace(' ', "_") == as_words)
    {
        return Some(Tier::Keyword);
    }
    if code.starts_with(as_words) {
        return Some(Tier::CodePrefix);
    }
    let word_prefix = keywords
        .any(|k| k.starts_with(query) || k.split([' ', '-']).any(|word| word.starts_with(query)))
        || code.split('_').any(|word| word.starts_with(as_words));
    if word_prefix {
        return Some(Tier::WordPrefix);
    }
    code.contains(as_words).then_some(Tier::CodeContains)
}

#[cfg(test)]
mod tests {
    use unicode_segmentation::UnicodeSegmentation as _;
    use unicode_width::{UnicodeWidthChar as _, UnicodeWidthStr as _};

    use super::*;
    use crate::app::state::EmojiMode;
    use crate::ui::{emoji, text};

    #[test]
    fn every_shortcode_is_valid_and_sanitises_cleanly_in_both_modes() {
        assert!(SHORTCODES.len() >= 80);
        assert!(EMOJI.len() > 1800);
        let every = SHORTCODES
            .iter()
            .copied()
            .chain(EMOJI.iter().map(|&(emoji, code, _)| (code, emoji)));
        for (name, raw_emoji) in every {
            assert!(!name.is_empty(), "empty shortcode name");
            assert!(
                name.chars().all(|c| c.is_ascii_lowercase()
                    || c.is_ascii_digit()
                    || matches!(c, '_' | '+' | '-')),
                "shortcode {name:?} must be lowercase ASCII"
            );
            assert!(!raw_emoji.is_empty(), "empty emoji for {name}");

            emoji::set_mode(EmojiMode::Full);
            let full = text::sanitize(raw_emoji);
            assert_eq!(
                full, raw_emoji,
                "{name} should already be canonical in Full mode"
            );
            assert_eq!(
                text::width(&full),
                2,
                "{name} ({raw_emoji:?}) should be 2 cells wide in Full mode"
            );
            for g in full.graphemes(true) {
                assert!(
                    emoji::drawable(g),
                    "{name}: {g:?} not drawable in Full mode"
                );
            }

            emoji::set_mode(EmojiMode::Compatible);
            let compat = text::sanitize(raw_emoji);
            assert!(!compat.is_empty(), "{name}: empty in Compatible mode");
            // Joined emoji compatible mode can't keep together (D47, D55)
            // come apart into their parts (😶‍🌫️ → 😶🌫️), so wider than 2.
            let compat_width = text::width(&compat);
            assert!(
                compat_width >= 1,
                "{name}: unexpected Compatible width {compat_width}"
            );
            for g in compat.graphemes(true) {
                assert!(
                    emoji::drawable(g),
                    "{name}: {g:?} not drawable in Compatible mode"
                );
                let cp_sum: usize = g.chars().map(|c| c.width().unwrap_or(0)).sum();
                assert_eq!(
                    g.width(),
                    cp_sum,
                    "{name}: {g:?} grapheme width disagrees with codepoint sum"
                );
            }
        }
        emoji::set_mode(EmojiMode::Full);
    }

    #[test]
    fn aliases_name_emoji_in_the_table_and_codes_are_unique() {
        for &(alias, emoji) in SHORTCODES {
            assert!(
                EMOJI.iter().any(|(e, _, _)| *e == emoji),
                "{alias}: {emoji:?} isn't in the table"
            );
        }
        let codes: std::collections::HashSet<&str> = EMOJI.iter().map(|(_, c, _)| *c).collect();
        assert_eq!(codes.len(), EMOJI.len(), "codes are unique");
        // Typable after `:` (State::active_shortcode_token).
        for (_, code, _) in EMOJI {
            assert!(
                code.chars()
                    .all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '+' | '-')),
                "{code}"
            );
        }
    }

    #[test]
    fn official_keywords_find_emoji() {
        let emoji = |query: &str, limit: usize| -> Vec<&str> {
            search_shortcodes(query, limit)
                .into_iter()
                .map(|(_, e)| e)
                .collect()
        };
        // CLDR's keywords: 😎 is "cool", and so is 🆒.
        let cool = emoji("cool", 8);
        assert_eq!(cool.first(), Some(&"😎"), "{cool:?}");
        assert!(cool.contains(&"🆒"), "{cool:?}");
        // Prefixes: the cook, the cookie and the Cook Islands.
        let coo = emoji("coo", 40);
        for wanted in ["🧑\u{200d}🍳", "🍪", "🇨🇰"] {
            assert!(coo.contains(&wanted), "{wanted}: {coo:?}");
        }
        // The everyday alias first, then the emoji whose own name it is.
        assert_eq!(emoji("sunglasses", 2), ["😎", "🕶️"]);
        assert_eq!(search_shortcodes("cookie", 1), [("cookie", "🍪")]);
        assert_eq!(
            search_shortcodes(":smiling_face_with_sung", 1),
            [("smiling_face_with_sunglasses", "😎")]
        );
    }

    #[test]
    fn search_shortcodes_ranks_and_deduplicates() {
        let empty = search_shortcodes("", 5);
        assert_eq!(empty.len(), 5);
        // "+1" and "thumbsup" both map to 👍, so 👍 appears only once.
        assert_eq!(empty.iter().filter(|(_, e)| *e == "👍").count(), 1);
        assert_eq!(
            search_shortcodes("thumbs", 8)
                .iter()
                .filter(|(_, e)| *e == "👍")
                .count(),
            1
        );

        let heart = search_shortcodes("heart", 8);
        assert_eq!(heart.first(), Some(&("heart", "❤️")));
        assert!(heart.contains(&("heart_eyes", "😍")), "{heart:?}");

        let fire = search_shortcodes(":fir:", 5);
        assert!(fire.contains(&("fire", "🔥")));
        assert_eq!(search_shortcodes("zzzqqq", 5), []);
    }

    #[test]
    fn typing_a_whole_code_gives_its_emoji() {
        assert_eq!(exact("thumbsup"), Some("👍"));
        assert_eq!(exact("cookie"), Some("🍪"));
        assert_eq!(exact("Smiling_Face_With_Sunglasses"), Some("😎"));
        assert_eq!(exact("flag_cook_islands"), Some("🇨🇰"));
        assert_eq!(exact("cool"), None, "a keyword alone is ambiguous");
    }
}
